ATTACK_CURRENT_TECHNIQUES = sorted(
    [k for k, v in ATTACK_TECHNIQUES.items() if not v["revoked"]],
    key=lambda t: [int(p) for p in t.lstrip("T").split(".")],
)
ATTACK_REVOKED = sorted(k for k, v in ATTACK_TECHNIQUES.items() if v["revoked"])
ATTACK_DEPRECATED = sorted(k for k, v in ATTACK_TECHNIQUES.items() if v["deprecated"])

# Reason recorded when an identifier cannot be resolved against the pinned bundle.
ATTACK_UNRESOLVED_REASON = (
    "This ATT&CK identifier is not present in the pinned Enterprise dataset, so no "
    "technique name is asserted for it. No name is substituted: an unknown "
    "technique id must stay unknown rather than acquire a plausible-looking label."
)


def technique(tid) -> dict | None:
    """Resolve one ATT&CK identifier. Returns None when it is not in the bundle.

    Fails closed by design. The caller decides how to display an unresolved id;
    this function never invents a name.
    """
    return ATTACK_TECHNIQUES.get(str(tid or "").strip().upper())


def technique_label(tid) -> str:
    """'T1595 Active Scanning' or the id alone when unresolved.

    An unresolved id renders as the id, with no description, because a placeholder
    string reads as an answer while a bare id reads as a question.
    """
    t = technique(tid)
    ident = str(tid or "").strip().upper()
    if not t:
        return ident
    return f"{ident} {t['name']}"


def technique_status(tid) -> str:
    """CURRENT / DEPRECATED / REVOKED / UNRESOLVED."""
    t = technique(tid)
    if not t:
        return "UNRESOLVED"
    if t["revoked"]:
        return "REVOKED"
    if t["deprecated"]:
        return "DEPRECATED"
    return "CURRENT"


def tactics_for(tid) -> list:
    t = technique(tid)
    return list(t["tactics"]) if t else []


def attack_summary(tids=()) -> list:
    """Resolve a set of identifiers for the mitre summary block.

    Every requested id appears in the output exactly once, so a caller can never
    silently lose one. Unresolved ids are returned with an empty description and
    status UNRESOLVED, never with placeholder text.
    """
    seen, out = set(), []
    for raw in tids or ():
        ident = str(raw or "").strip().upper()
        if not ident or ident in seen:
            continue
        if ident.lower() in {"none", "not applicable", "n/a", "na"}:
            continue
        seen.add(ident)
        t = technique(ident)
        out.append({
            "id": ident,
            # Empty, not placeholder text. A reader must be able to tell that no
            # name was resolved; that placeholder told them nothing while
            # looking like an answer.
            "description": (t or {}).get("name", ""),
            "status": technique_status(ident),
            "tactics": tactics_for(ident),
            "revoked": bool((t or {}).get("revoked")),
            "url": (t or {}).get("url", ""),
        })
    return out


